catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
	//MSSRBXCE-18
    if (isLoading || newValue == '') {
        g_form.setMandatory('business_process_definition', true);
        g_form.setMandatory('client', false);
        g_form.setMandatory('active', true);

        g_form.setReadOnly('client', true);
        g_form.setReadOnly('business_process_definition', true);
        g_form.setReadOnly('active', true);

    } else {
        g_form.setReadOnly('client', false);
        g_form.setMandatory('client', true);
        g_form.setReadOnly('business_process_definition', false);
        g_form.setReadOnly('active', false);
        g_form.setMandatory('active', false);
    }
    //Type appropriate comment here, and begin script below

}
